INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, track, track_order, is_core, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-tenses-b1-07-01', 'lesson-tenses-b1-07', 1, 'sentence', 'If you heat ice, it melts.', 'Se você aquece gelo, ele derrete.', '/ɪf juː hiːt aɪs ɪt mɛlts/', 'Zero conditional: if + presente, presente. Verdade que sempre acontece.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"heat","pos":"verb","ipa":"/hiːt/","gloss":"aquecer"},{"surface":"ice","pos":"noun","ipa":"/aɪs/","gloss":"gelo"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"melts","pos":"verb","ipa":"/mɛlts/","gloss":"derrete"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-07-02', 'lesson-tenses-b1-07', 2, 'sentence', 'If I drink coffee at night, I can''t sleep.', 'Se tomo café à noite, não consigo dormir.', '/ɪf aɪ drɪŋk ˈkɔːfi æt naɪt aɪ kænt sliːp/', 'Zero conditional para hábito pessoal: sempre que acontece.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"drink","pos":"verb","ipa":"/drɪŋk/","gloss":"beber"},{"surface":"coffee","pos":"noun","ipa":"/ˈkɔːfi/","gloss":"café"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"can''t","pos":"auxiliary verb","ipa":"/kænt/","gloss":"não poder"},{"surface":"sleep","pos":"verb","ipa":"/sliːp/","gloss":"dormir"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-07-03', 'lesson-tenses-b1-07', 3, 'sentence', 'If it rains tomorrow, we will stay home.', 'Se chover amanhã, vamos ficar em casa.', '/ɪf ɪt reɪnz təˈmɑːroʊ wiː wɪl steɪ hoʊm/', 'First conditional: if + presente, will + verbo. Em português usamos o futuro do subjuntivo ("chover"); em inglês, presente.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"rains","pos":"verb","ipa":"/reɪnz/","gloss":"chove"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"stay","pos":"verb","ipa":"/steɪ/","gloss":"ficar"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-07-04', 'lesson-tenses-b1-07', 4, 'sentence', 'If you study, you will pass the test.', 'Se você estudar, vai passar na prova.', '/ɪf juː ˈstʌdi juː wɪl pæs ðə tɛst/', 'Nunca "if you will study": depois de "if", presente.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"study","pos":"verb","ipa":"/ˈstʌdi/","gloss":"estudar"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"pass","pos":"noun","ipa":"/pæs/","gloss":"cartão, passe"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"test","pos":"noun","ipa":"/tɛst/","gloss":"exame, teste"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-07-05', 'lesson-tenses-b1-07', 5, 'sentence', 'I''ll call you if I need help.', 'Te ligo se precisar de ajuda.', '/aɪl kɔːl juː ɪf aɪ niːd hɛlp/', 'A oração com "if" pode vir no fim, sem vírgula.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-07-06', 'lesson-tenses-b1-07', 6, 'sentence', 'Unless you hurry, you will miss the bus.', 'A menos que se apresse, vai perder o ônibus.', '/ənˈlɛs juː ˈhɜːri juː wɪl mɪs ðə bʌs/', '"Unless" = "if not". Não use negativa depois de "unless".', '[]'::jsonb, '[{"surface":"Unless","pos":"conjunction","ipa":"/ənˈlɛs/","gloss":"a menos que"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"hurry","pos":"noun","ipa":"/ˈhɜːri/","gloss":"pressa"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"miss","pos":"verb","ipa":"/mɪs/","gloss":"errar, perder; sentir falta"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-07-07', 'lesson-tenses-b1-07', 7, 'sentence', 'If you see Anna, tell her to call me.', 'Se vir a Anna, diga para ela me ligar.', '/ɪf juː siː ˈænə tɛl hɜːr tuː kɔːl miː/', 'Condicional com imperativo: if + presente, ordem.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"see","pos":"verb","ipa":"/siː/","gloss":"ver, entender"},{"surface":"Anna","pos":"proper noun","ipa":"/ˈænə/","gloss":"Anna"},{"surface":"tell","pos":"verb","ipa":"/tɛl/","gloss":"contar, dizer"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-07-08', 'lesson-tenses-b1-07', 8, 'sentence', 'When I get home, I will text you.', 'Quando eu chegar em casa, te mando mensagem.', '/wɛn aɪ ɡɛt hoʊm aɪ wɪl tɛkst juː/', '"When" também pede presente para futuro: "when I get", não "when I will get".', '[]'::jsonb, '[{"surface":"When","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"text","pos":"verb","ipa":"/tɛkst/","gloss":"mandar mensagem"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-07-09', 'lesson-tenses-b1-07', 9, 'sentence', 'As soon as the store opens, I will buy it.', 'Assim que a loja abrir, vou comprar.', '/æz suːn æz ðə stɔːr ˈoʊpənz aɪ wɪl baɪ ɪt/', '"As soon as" + presente com sentido de futuro.', '[]'::jsonb, '[{"surface":"As","pos":"conjunction","ipa":"/æz/","gloss":"como"},{"surface":"soon","pos":"adverb","ipa":"/suːn/","gloss":"logo"},{"surface":"as","pos":"conjunction","ipa":"/æz/","gloss":"como"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"store","pos":"noun","ipa":"/stɔːr/","gloss":"loja, mercado"},{"surface":"opens","pos":"verb","ipa":"/ˈoʊpənz/","gloss":"abre"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"buy","pos":"verb","ipa":"/baɪ/","gloss":"comprar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-07-10', 'lesson-tenses-b1-07', 10, 'sentence', 'If the train is late, we might miss the show.', 'Se o trem atrasar, talvez a gente perca o show.', '/ɪf ðə treɪn ɪz leɪt wiː maɪt mɪs ðə ʃoʊ/', '"Might" no lugar de "will" deixa a consequência menos certa.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"train","pos":"noun","ipa":"/treɪn/","gloss":"trem"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"might","pos":"modal verb","ipa":"/maɪt/","gloss":"talvez, poderia"},{"surface":"miss","pos":"verb","ipa":"/mɪs/","gloss":"errar, perder; sentir falta"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"show","pos":"verb","ipa":"/ʃoʊ/","gloss":"aparecer (show up)"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-tenses-b1-08-01', 'lesson-tenses-b1-08', 1, 'sentence', 'If I had more money, I would travel more.', 'Se eu tivesse mais dinheiro, viajaria mais.', '/ɪf aɪ hæd mɔːr ˈmʌni aɪ wʊd ˈtrævəl mɔːr/', 'Second conditional: if + passado, would + verbo. Situação imaginária agora.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"money","pos":"noun","ipa":"/ˈmʌni/","gloss":"dinheiro"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"travel","pos":"verb","ipa":"/ˈtrævəl/","gloss":"viajar"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-08-02', 'lesson-tenses-b1-08', 2, 'sentence', 'If I were you, I would accept the offer.', 'Se eu fosse você, aceitaria a oferta.', '/ɪf aɪ wɜːr juː aɪ wʊd əkˈsɛpt ðə ˈɔːfər/', '"If I were you" é a forma padrão para dar conselho; "were" para todas as pessoas.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"accept","pos":"verb","ipa":"/əkˈsɛpt/","gloss":"aceitar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"offer","pos":"noun","ipa":"/ˈɔːfər/","gloss":"oferta"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-08-03', 'lesson-tenses-b1-08', 3, 'sentence', 'If she lived closer, we would see her more.', 'Se ela morasse mais perto, a veríamos mais.', '/ɪf ʃiː lɪvd ˈkloʊsər wiː wʊd siː hɜːr mɔːr/', 'O passado aqui não é tempo passado: é hipótese, como o imperfeito do subjuntivo.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"lived","pos":"verb","ipa":"/lɪvd/","gloss":"morou, viveu"},{"surface":"closer","pos":"adverb","ipa":"/ˈkloʊsər/","gloss":"mais perto"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"see","pos":"verb","ipa":"/siː/","gloss":"ver, entender"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-08-04', 'lesson-tenses-b1-08', 4, 'sentence', 'What would you do if you won the lottery?', 'O que você faria se ganhasse na loteria?', '/wʌt wʊd juː duː ɪf juː wʌn ðə ˈlɑːtəri/', 'Pergunta hipotética clássica.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"won","pos":"verb","ipa":"/wʌn/","gloss":"ganhou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"lottery","pos":"noun","ipa":"/ˈlɑːtəri/","gloss":"loteria"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-08-05', 'lesson-tenses-b1-08', 5, 'sentence', 'If I knew the answer, I would tell you.', 'Se eu soubesse a resposta, te contaria.', '/ɪf aɪ nuː ðə ˈænsər aɪ wʊd tɛl juː/', 'Implica que não sei a resposta.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"knew","pos":"verb","ipa":"/nuː/","gloss":"sabia, conheceu"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"answer","pos":"noun","ipa":"/ˈænsər/","gloss":"resposta"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"tell","pos":"verb","ipa":"/tɛl/","gloss":"contar, dizer"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-08-06', 'lesson-tenses-b1-08', 6, 'sentence', 'I wouldn''t do that if I were you.', 'Eu não faria isso se fosse você.', '/aɪ ˈwʊdənt duː ðæt ɪf aɪ wɜːr juː/', 'Negativa: "wouldn''t" + verbo.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"wouldn''t","pos":"verb","ipa":"/ˈwʊdənt/","gloss":"não faria (would not)"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-08-07', 'lesson-tenses-b1-08', 7, 'sentence', 'If we had a car, we could go to the beach.', 'Se tivéssemos carro, poderíamos ir à praia.', '/ɪf wiː hæd ə kɑːr wiː kʊd ɡoʊ tuː ðə biːtʃ/', '"Could" = "would be able to".', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"go","pos":"verb","ipa":"/ɡoʊ/","gloss":"ir"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"beach","pos":"noun","ipa":"/biːtʃ/","gloss":"praia"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-08-08', 'lesson-tenses-b1-08', 8, 'sentence', 'If it weren''t so expensive, I would buy it.', 'Se não fosse tão caro, eu compraria.', '/ɪf ɪt wɜːrnt soʊ ɪkˈspɛnsɪv aɪ wʊd baɪ ɪt/', 'Negativa na oração com "if": "weren''t".', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"weren''t","pos":"verb","ipa":"/wɜːrnt/","gloss":"não eram, não estavam (were not)"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"expensive","pos":"adjective","ipa":"/ɪkˈspɛnsɪv/","gloss":"caro"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"buy","pos":"verb","ipa":"/baɪ/","gloss":"comprar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-08-09', 'lesson-tenses-b1-08', 9, 'sentence', 'I wish I spoke French.', 'Queria falar francês.', '/aɪ wɪʃ aɪ spoʊk frɛntʃ/', '"I wish" + passado = desejo sobre o presente, mesma lógica da segunda condicional.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"wish","pos":"verb","ipa":"/wɪʃ/","gloss":"desejar"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"spoke","pos":"verb","ipa":"/spoʊk/","gloss":"falou"},{"surface":"French","pos":"noun","ipa":"/frɛntʃ/","gloss":"francês"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-08-10', 'lesson-tenses-b1-08', 10, 'sentence', 'If I could live anywhere, I would choose Lisbon.', 'Se eu pudesse morar em qualquer lugar, escolheria Lisboa.', '/ɪf aɪ kʊd lɪv ˈɛniwɛr aɪ wʊd tʃuːz ˈlɪzbən/', '"Could" no lugar de "had" para capacidade imaginária.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"live","pos":"verb","ipa":"/lɪv/","gloss":"morar, viver"},{"surface":"anywhere","pos":"adverb","ipa":"/ˈɛniwɛr/","gloss":"em qualquer lugar"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"choose","pos":"verb","ipa":"/tʃuːz/","gloss":"escolher"},{"surface":"Lisbon","pos":"proper noun","ipa":"/ˈlɪzbən/","gloss":"Lisboa"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-tenses-b1-09-01', 'lesson-tenses-b1-09', 1, 'sentence', 'If I had left earlier, I would have caught the train.', 'Se eu tivesse saído mais cedo, teria pegado o trem.', '/ɪf aɪ hæd lɛft ˈɜːrliər aɪ wʊd hæv kɔːt ðə treɪn/', 'Third conditional: if + past perfect, would have + particípio. O passado não aconteceu assim.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"},{"surface":"earlier","pos":"adverb","ipa":"/ˈɜːrliər/","gloss":"mais cedo, antes"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"caught","pos":"verb","ipa":"/kɔːt/","gloss":"pegou, pegado"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"train","pos":"noun","ipa":"/treɪn/","gloss":"trem"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-09-02', 'lesson-tenses-b1-09', 2, 'sentence', 'If you had told me, I would have helped.', 'Se você tivesse me contado, eu teria ajudado.', '/ɪf juː hæd toʊld miː aɪ wʊd hæv hɛlpt/', 'Arrependimento ou crítica sobre o passado.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"told","pos":"verb","ipa":"/toʊld/","gloss":"contou, disse"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"helped","pos":"verb","ipa":"/hɛlpt/","gloss":"ajudou"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-09-03', 'lesson-tenses-b1-09', 3, 'sentence', 'We wouldn''t have got lost if we had used the map.', 'Não teríamos nos perdido se tivéssemos usado o mapa.', '/wiː ˈwʊdənt hæv ɡɑːt lɔːst ɪf wiː hæd juːzd ðə mæp/', 'A oração com "if" pode vir depois.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"wouldn''t","pos":"verb","ipa":"/ˈwʊdənt/","gloss":"não faria (would not)"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"got","pos":"verb","ipa":"/ɡɑːt/","gloss":"conseguiu, pegou"},{"surface":"lost","pos":"adjective","ipa":"/lɔːst/","gloss":"perdido; perdeu"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"used","pos":"verb","ipa":"/juːzd/","gloss":"usou, usado"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"map","pos":"noun","ipa":"/mæp/","gloss":"mapa"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-09-04', 'lesson-tenses-b1-09', 4, 'sentence', 'If she had studied, she would have passed.', 'Se ela tivesse estudado, teria passado.', '/ɪf ʃiː hæd ˈstʌdid ʃiː wʊd hæv pæst/', 'Na fala: "she''d have passed".', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"studied","pos":"verb","ipa":"/ˈstʌdid/","gloss":"estudou, estudado"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"passed","pos":"verb","ipa":"/pæst/","gloss":"passou"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-09-05', 'lesson-tenses-b1-09', 5, 'sentence', 'What would you have done in my place?', 'O que você teria feito no meu lugar?', '/wʌt wʊd juː hæv dʌn ɪn maɪ pleɪs/', 'Pergunta sobre um passado imaginário.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"done","pos":"adjective","ipa":"/dʌn/","gloss":"pronto, feito"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"place","pos":"noun","ipa":"/pleɪs/","gloss":"lugar"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-09-06', 'lesson-tenses-b1-09', 6, 'sentence', 'If it hadn''t rained, we would have gone to the park.', 'Se não tivesse chovido, teríamos ido ao parque.', '/ɪf ɪt ˈhædənt reɪnd wiː wʊd hæv ɡɔːn tuː ðə pɑːrk/', 'Negativa: "hadn''t" + particípio.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"hadn''t","pos":"verb","ipa":"/ˈhædənt/","gloss":"não tinha (had not)"},{"surface":"rained","pos":"verb","ipa":"/reɪnd/","gloss":"choveu"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"gone","pos":"verb","ipa":"/ɡɔːn/","gloss":"ido (particípio de go)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"park","pos":"verb","ipa":"/pɑːrk/","gloss":"estacionar"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-09-07', 'lesson-tenses-b1-09', 7, 'sentence', 'I would have called you if I had known.', 'Eu teria te ligado se soubesse.', '/aɪ wʊd hæv kɔːld juː ɪf aɪ hæd noʊn/', 'Em português falado usamos "se soubesse"; em inglês precisa de "had known".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"called","pos":"verb","ipa":"/kɔːld/","gloss":"ligou, chamou"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"known","pos":"verb","ipa":"/noʊn/","gloss":"sabido, conhecido"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-09-08', 'lesson-tenses-b1-09', 8, 'sentence', 'I wish I had listened to you.', 'Queria ter te escutado.', '/aɪ wɪʃ aɪ hæd ˈlɪsənd tuː juː/', '"I wish" + past perfect = arrependimento sobre o passado.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"wish","pos":"verb","ipa":"/wɪʃ/","gloss":"desejar"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"listened","pos":"verb","ipa":"/ˈlɪsənd/","gloss":"ouviu"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-09-09', 'lesson-tenses-b1-09', 9, 'sentence', 'If I had taken that job, I would live in Paris now.', 'Se eu tivesse aceitado aquele emprego, moraria em Paris agora.', '/ɪf aɪ hæd ˈteɪkən ðæt dʒɑːb aɪ wʊd lɪv ɪn ˈpærɪs naʊ/', 'Condicional mista: passado imaginado com resultado no presente.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"taken","pos":"verb","ipa":"/ˈteɪkən/","gloss":"pegado, levado"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"job","pos":"noun","ipa":"/dʒɑːb/","gloss":"trabalho"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"live","pos":"verb","ipa":"/lɪv/","gloss":"morar, viver"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"Paris","pos":"proper noun","ipa":"/ˈpærɪs/","gloss":"Paris"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-09-10', 'lesson-tenses-b1-09', 10, 'sentence', 'You should have told me earlier.', 'Você deveria ter me contado antes.', '/juː ʃʊd hæv toʊld miː ˈɜːrliər/', '"Should have" + particípio = crítica sobre o passado, parente da terceira condicional.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"told","pos":"verb","ipa":"/toʊld/","gloss":"contou, disse"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"earlier","pos":"adverb","ipa":"/ˈɜːrliər/","gloss":"mais cedo, antes"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-tenses-b1-10-01', 'lesson-tenses-b1-10', 1, 'sentence', 'English is spoken all over the world.', 'Inglês é falado no mundo todo.', '/ˈɪŋɡlɪʃ ɪz ˈspoʊkən ɔːl ˈoʊvər ðə wɜːrld/', 'Passiva: be + particípio. Quem fala não importa.', '[]'::jsonb, '[{"surface":"English","pos":"proper noun","ipa":"/ˈɪŋɡlɪʃ/","gloss":"inglês"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"spoken","pos":"verb","ipa":"/ˈspoʊkən/","gloss":"falado"},{"surface":"all","pos":"determiner","ipa":"/ɔːl/","gloss":"tudo, todos"},{"surface":"over","pos":"preposition","ipa":"/ˈoʊvər/","gloss":"por cima; superado"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"world","pos":"noun","ipa":"/wɜːrld/","gloss":"mundo"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-10-02', 'lesson-tenses-b1-10', 2, 'sentence', 'The office is cleaned every night.', 'O escritório é limpo toda noite.', '/ðə ˈɔːfɪs ɪz kliːnd ˈɛvri naɪt/', 'Presente simples na passiva: "is cleaned".', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"office","pos":"noun","ipa":"/ˈɔːfɪs/","gloss":"escritório, balcão"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"cleaned","pos":"verb","ipa":"/kliːnd/","gloss":"limpo"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-10-03', 'lesson-tenses-b1-10', 3, 'sentence', 'This bridge was built in 1920.', 'Esta ponte foi construída em 1920.', '/ðɪs brɪdʒ wɑːz bɪlt ɪn/', 'Passado na passiva: "was built".', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"bridge","pos":"noun","ipa":"/brɪdʒ/","gloss":"ponte"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"built","pos":"verb","ipa":"/bɪlt/","gloss":"construiu"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-10-04', 'lesson-tenses-b1-10', 4, 'sentence', 'My bike was stolen last week.', 'Minha bicicleta foi roubada semana passada.', '/maɪ baɪk wɑːz ˈstoʊlən læst wiːk/', 'Não sabemos quem roubou, então a passiva é natural.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"bike","pos":"noun","ipa":"/baɪk/","gloss":"bicicleta"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"stolen","pos":"verb","ipa":"/ˈstoʊlən/","gloss":"roubado"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"week","pos":"noun","ipa":"/wiːk/","gloss":"semana"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-10-05', 'lesson-tenses-b1-10', 5, 'sentence', 'The book was written by a young nurse.', 'O livro foi escrito por uma jovem enfermeira.', '/ðə bʊk wɑːz ˈrɪtən baɪ ə jʌŋ nɜːrs/', '"By" apresenta o agente quando ele é informação nova.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"book","pos":"verb","ipa":"/bʊk/","gloss":"reservar; livro"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"written","pos":"verb","ipa":"/ˈrɪtən/","gloss":"escrito"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"young","pos":"adjective","ipa":"/jʌŋ/","gloss":"jovem"},{"surface":"nurse","pos":"noun","ipa":"/nɜːrs/","gloss":"enfermeiro"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-10-06', 'lesson-tenses-b1-10', 6, 'sentence', 'Are credit cards accepted here?', 'Aceitam cartão de crédito aqui?', '/ɑːr ˈkrɛdɪt kɑːrdz əkˈsɛptɪd hɪr/', 'Pergunta na passiva: be antes do sujeito. Em português usamos sujeito indeterminado.', '[]'::jsonb, '[{"surface":"Are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"credit","pos":"noun","ipa":"/ˈkrɛdɪt/","gloss":"crédito"},{"surface":"cards","pos":"noun","ipa":"/kɑːrdz/","gloss":"cartões"},{"surface":"accepted","pos":"verb","ipa":"/əkˈsɛptɪd/","gloss":"aceito"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-10-07', 'lesson-tenses-b1-10', 7, 'sentence', 'Breakfast is served from seven to ten.', 'O café da manhã é servido das sete às dez.', '/ˈbrɛkfəst ɪz sɜːrvd frʌm ˈsɛvən tuː tɛn/', 'Passiva comum em avisos de hotel.', '[]'::jsonb, '[{"surface":"Breakfast","pos":"noun","ipa":"/ˈbrɛkfəst/","gloss":"café da manhã"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"served","pos":"verb","ipa":"/sɜːrvd/","gloss":"servido"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"seven","pos":"numeral","ipa":"/ˈsɛvən/","gloss":"sete"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"ten","pos":"numeral","ipa":"/tɛn/","gloss":"dez"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-10-08', 'lesson-tenses-b1-10', 8, 'sentence', 'I was born in Recife.', 'Nasci em Recife.', '/aɪ wɑːz bɔːrn ɪn rɛˈsiːfeɪ/', '"Be born" é sempre passiva em inglês: nunca "I born".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"born","pos":"verb","ipa":"/bɔːrn/","gloss":"nascido (be born = nascer)"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"Recife","pos":"proper noun","ipa":"/rɛˈsiːfeɪ/","gloss":"Recife"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-10-09', 'lesson-tenses-b1-10', 9, 'sentence', 'The meeting was canceled.', 'A reunião foi cancelada.', '/ðə ˈmiːtɪŋ wɑːz ˈkænsəld/', 'Aviso típico: o agente é óbvio ou irrelevante.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"canceled","pos":"verb","ipa":"/ˈkænsəld/","gloss":"cancelado"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-10-10', 'lesson-tenses-b1-10', 10, 'sentence', 'Were you invited to the party?', 'Você foi convidado para a festa?', '/wɜːr juː ɪnˈvaɪtɪd tuː ðə ˈpɑːrti/', 'Passado na passiva, forma de pergunta.', '[]'::jsonb, '[{"surface":"Were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"invited","pos":"verb","ipa":"/ɪnˈvaɪtɪd/","gloss":"convidado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"party","pos":"noun","ipa":"/ˈpɑːrti/","gloss":"festa"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-tenses-b1-11-01', 'lesson-tenses-b1-11', 1, 'sentence', 'The package has been delivered.', 'O pacote foi entregue.', '/ðə ˈpækɪdʒ hæz bɪn dɪˈlɪvərd/', 'Present perfect passivo: has/have been + particípio. Resultado agora.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"package","pos":"noun","ipa":"/ˈpækɪdʒ/","gloss":"pacote"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"delivered","pos":"verb","ipa":"/dɪˈlɪvərd/","gloss":"entregue"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-11-02', 'lesson-tenses-b1-11', 2, 'sentence', 'The results will be announced tomorrow.', 'Os resultados serão anunciados amanhã.', '/ðə rɪˈzʌlts wɪl biː əˈnaʊnst təˈmɑːroʊ/', 'Futuro passivo: will be + particípio.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"results","pos":"noun","ipa":"/rɪˈzʌlts/","gloss":"resultados"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"announced","pos":"verb","ipa":"/əˈnaʊnst/","gloss":"anunciado"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-11-03', 'lesson-tenses-b1-11', 3, 'sentence', 'The road is being repaired.', 'A estrada está sendo consertada.', '/ðə roʊd ɪz ˈbiːɪŋ rɪˈpɛrd/', 'Contínuo passivo: is being + particípio.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"road","pos":"noun","ipa":"/roʊd/","gloss":"estrada"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"being","pos":"verb","ipa":"/ˈbiːɪŋ/","gloss":"sendo"},{"surface":"repaired","pos":"verb","ipa":"/rɪˈpɛrd/","gloss":"consertado"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-11-04', 'lesson-tenses-b1-11', 4, 'sentence', 'This form must be signed.', 'Este formulário precisa ser assinado.', '/ðɪs fɔːrm mʌst biː saɪnd/', 'Modal passivo: modal + be + particípio.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"form","pos":"noun","ipa":"/fɔːrm/","gloss":"formulário"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"signed","pos":"verb","ipa":"/saɪnd/","gloss":"assinado"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-11-05', 'lesson-tenses-b1-11', 5, 'sentence', 'The tickets can be bought online.', 'Os ingressos podem ser comprados online.', '/ðə ˈtɪkɪts kæn biː bɔːt ˌɑːnˈlaɪn/', '"Can be" + particípio = é possível.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"tickets","pos":"noun","ipa":"/ˈtɪkɪts/","gloss":"ingressos"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"bought","pos":"verb","ipa":"/bɔːt/","gloss":"comprou"},{"surface":"online","pos":"adverb","ipa":"/ˌɑːnˈlaɪn/","gloss":"na internet"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-11-06', 'lesson-tenses-b1-11', 6, 'sentence', 'All the rooms have been booked.', 'Todos os quartos foram reservados.', '/ɔːl ðə ruːmz hæv bɪn bʊkt/', 'Plural: "have been".', '[]'::jsonb, '[{"surface":"All","pos":"determiner","ipa":"/ɔːl/","gloss":"tudo, todos"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"rooms","pos":"noun","ipa":"/ruːmz/","gloss":"quartos"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"booked","pos":"adjective","ipa":"/bʊkt/","gloss":"reservado, lotado"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-11-07', 'lesson-tenses-b1-11', 7, 'sentence', 'The house was being painted when we arrived.', 'A casa estava sendo pintada quando chegamos.', '/ðə haʊs wɑːz ˈbiːɪŋ ˈpeɪntɪd wɛn wiː əˈraɪvd/', 'Passado contínuo passivo: was being + particípio.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"house","pos":"noun","ipa":"/haʊs/","gloss":"casa"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"being","pos":"verb","ipa":"/ˈbiːɪŋ/","gloss":"sendo"},{"surface":"painted","pos":"verb","ipa":"/ˈpeɪntɪd/","gloss":"pintado"},{"surface":"when","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"arrived","pos":"verb","ipa":"/əˈraɪvd/","gloss":"chegou"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-11-08', 'lesson-tenses-b1-11', 8, 'sentence', 'The work had been finished before noon.', 'O trabalho tinha sido terminado antes do meio-dia.', '/ðə wɜːrk hæd bɪn ˈfɪnɪʃt bɪˈfɔːr nuːn/', 'Past perfect passivo: had been + particípio.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"finished","pos":"verb","ipa":"/ˈfɪnɪʃt/","gloss":"terminou, terminado"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"noon","pos":"noun","ipa":"/nuːn/","gloss":"meio-dia"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-11-09', 'lesson-tenses-b1-11', 9, 'sentence', 'I got stuck in traffic.', 'Fiquei preso no trânsito.', '/aɪ ɡɑːt stʌk ɪn ˈtræfɪk/', '"Get" + particípio é a passiva informal da fala.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"got","pos":"verb","ipa":"/ɡɑːt/","gloss":"conseguiu, pegou"},{"surface":"stuck","pos":"adjective","ipa":"/stʌk/","gloss":"preso"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"traffic","pos":"noun","ipa":"/ˈtræfɪk/","gloss":"trânsito"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-11-10', 'lesson-tenses-b1-11', 10, 'sentence', 'He got fired last month.', 'Ele foi demitido mês passado.', '/hiː ɡɑːt ˈfaɪərd læst mʌnθ/', '"Get fired" é mais comum na fala do que "was fired".', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"got","pos":"verb","ipa":"/ɡɑːt/","gloss":"conseguiu, pegou"},{"surface":"fired","pos":"verb","ipa":"/ˈfaɪərd/","gloss":"demitido"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"month","pos":"noun","ipa":"/mʌnθ/","gloss":"mês"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-tenses-b1-12-01', 'lesson-tenses-b1-12', 1, 'sentence', 'She said she was tired.', 'Ela disse que estava cansada.', '/ʃiː sɛd ʃiː wɑːz ˈtaɪərd/', 'Presente vira passado: "I am tired" → "she was tired".', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"said","pos":"verb","ipa":"/sɛd/","gloss":"disse, dito"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"tired","pos":"adjective","ipa":"/ˈtaɪərd/","gloss":"cansado"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-12-02', 'lesson-tenses-b1-12', 2, 'sentence', 'He told me he lived in Porto.', 'Ele me disse que morava no Porto.', '/hiː toʊld miː hiː lɪvd ɪn ˈpɔːrtoʊ/', '"Tell" pede objeto (told me); "say" não (said that).', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"told","pos":"verb","ipa":"/toʊld/","gloss":"contou, disse"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"lived","pos":"verb","ipa":"/lɪvd/","gloss":"morou, viveu"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"Porto","pos":"proper noun","ipa":"/ˈpɔːrtoʊ/","gloss":"Porto"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-12-03', 'lesson-tenses-b1-12', 3, 'sentence', 'They said they had finished.', 'Disseram que tinham terminado.', '/ðeɪ sɛd ðeɪ hæd ˈfɪnɪʃt/', 'Passado ou present perfect vira past perfect.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"said","pos":"verb","ipa":"/sɛd/","gloss":"disse, dito"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"finished","pos":"verb","ipa":"/ˈfɪnɪʃt/","gloss":"terminou, terminado"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-12-04', 'lesson-tenses-b1-12', 4, 'sentence', 'She said she would call later.', 'Ela disse que ligaria mais tarde.', '/ʃiː sɛd ʃiː wʊd kɔːl ˈleɪtər/', '"Will" vira "would".', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"said","pos":"verb","ipa":"/sɛd/","gloss":"disse, dito"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"later","pos":"adverb","ipa":"/ˈleɪtər/","gloss":"mais tarde"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-12-05', 'lesson-tenses-b1-12', 5, 'sentence', 'He said he could help us.', 'Ele disse que podia nos ajudar.', '/hiː sɛd hiː kʊd hɛlp ʌs/', '"Can" vira "could".', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"said","pos":"verb","ipa":"/sɛd/","gloss":"disse, dito"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-12-06', 'lesson-tenses-b1-12', 6, 'sentence', 'You said you were coming!', 'Você disse que vinha!', '/juː sɛd juː wɜːr ˈkʌmɪŋ/', 'Presente contínuo vira passado contínuo.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"said","pos":"verb","ipa":"/sɛd/","gloss":"disse, dito"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"coming","pos":"verb","ipa":"/ˈkʌmɪŋ/","gloss":"vindo"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-12-07', 'lesson-tenses-b1-12', 7, 'sentence', 'She told us the store was closed.', 'Ela nos disse que a loja estava fechada.', '/ʃiː toʊld ʌs ðə stɔːr wɑːz kloʊzd/', '"That" pode ser omitido depois de "said" e "told".', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"told","pos":"verb","ipa":"/toʊld/","gloss":"contou, disse"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"store","pos":"noun","ipa":"/stɔːr/","gloss":"loja, mercado"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"closed","pos":"verb","ipa":"/kloʊzd/","gloss":"fechou, fechado"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-12-08', 'lesson-tenses-b1-12', 8, 'sentence', 'He says he is busy.', 'Ele diz que está ocupado.', '/hiː sɛz hiː ɪz ˈbɪzi/', 'Com "says" no presente, o tempo não muda.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"says","pos":"verb","ipa":"/sɛz/","gloss":"diz"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"busy","pos":"adjective","ipa":"/ˈbɪzi/","gloss":"ocupado"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-12-09', 'lesson-tenses-b1-12', 9, 'sentence', 'I told you it would rain.', 'Eu te disse que ia chover.', '/aɪ toʊld juː ɪt wʊd reɪn/', 'Previsão passada: "will" vira "would".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"told","pos":"verb","ipa":"/toʊld/","gloss":"contou, disse"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"rain","pos":"verb","ipa":"/reɪn/","gloss":"chover; chuva"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-12-10', 'lesson-tenses-b1-12', 10, 'sentence', 'She said she had seen the movie the day before.', 'Ela disse que tinha visto o filme no dia anterior.', '/ʃiː sɛd ʃiː hæd siːn ðə ˈmuːvi ðə deɪ bɪˈfɔːr/', '"Yesterday" vira "the day before" quando o contexto mudou.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"said","pos":"verb","ipa":"/sɛd/","gloss":"disse, dito"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"seen","pos":"verb","ipa":"/siːn/","gloss":"visto"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"movie","pos":"noun","ipa":"/ˈmuːvi/","gloss":"filme"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-tenses-b1-13-01', 'lesson-tenses-b1-13', 1, 'sentence', 'She asked me where I lived.', 'Ela me perguntou onde eu morava.', '/ʃiː æskt miː wɛr aɪ lɪvd/', 'Pergunta indireta: ordem de afirmação, sem "did" e sem inversão.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"asked","pos":"verb","ipa":"/æskt/","gloss":"perguntou, pediu"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"lived","pos":"verb","ipa":"/lɪvd/","gloss":"morou, viveu"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-13-02', 'lesson-tenses-b1-13', 2, 'sentence', 'He asked if I was ready.', 'Ele perguntou se eu estava pronto.', '/hiː æskt ɪf aɪ wɑːz ˈrɛdi/', 'Pergunta de sim ou não vira "if" ou "whether".', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"asked","pos":"verb","ipa":"/æskt/","gloss":"perguntou, pediu"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"ready","pos":"adjective","ipa":"/ˈrɛdi/","gloss":"pronto"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-13-03', 'lesson-tenses-b1-13', 3, 'sentence', 'They asked what time the show started.', 'Perguntaram a que horas o show começava.', '/ðeɪ æskt wʌt taɪm ðə ʃoʊ ˈstɑːrtɪd/', 'Nada de "what time did the show start" no indireto.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"asked","pos":"verb","ipa":"/æskt/","gloss":"perguntou, pediu"},{"surface":"what","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"show","pos":"verb","ipa":"/ʃoʊ/","gloss":"aparecer (show up)"},{"surface":"started","pos":"verb","ipa":"/ˈstɑːrtɪd/","gloss":"começado"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-13-04', 'lesson-tenses-b1-13', 4, 'sentence', 'Do you know where the station is?', 'Você sabe onde fica a estação?', '/duː juː noʊ wɛr ðə ˈsteɪʃən ɪz/', 'Pergunta indireta educada: "where the station is", não "where is the station".', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"know","pos":"verb","ipa":"/noʊ/","gloss":"saber"},{"surface":"where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"station","pos":"noun","ipa":"/ˈsteɪʃən/","gloss":"estação"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-13-05', 'lesson-tenses-b1-13', 5, 'sentence', 'Can you tell me how much it costs?', 'Pode me dizer quanto custa?', '/kæn juː tɛl miː haʊ mʌtʃ ɪt kɔːsts/', 'Mais educado que "How much does it cost?".', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"tell","pos":"verb","ipa":"/tɛl/","gloss":"contar, dizer"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"how","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"much","pos":"adverb","ipa":"/mʌtʃ/","gloss":"quanto (how much)"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"costs","pos":"verb","ipa":"/kɔːsts/","gloss":"custa"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-13-06', 'lesson-tenses-b1-13', 6, 'sentence', 'She told me to wait outside.', 'Ela me mandou esperar lá fora.', '/ʃiː toʊld miː tuː weɪt ˌaʊtˈsaɪd/', 'Ordem: tell + pessoa + to + verbo.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"told","pos":"verb","ipa":"/toʊld/","gloss":"contou, disse"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"wait","pos":"noun","ipa":"/weɪt/","gloss":"espera; esperar"},{"surface":"outside","pos":"adverb","ipa":"/ˌaʊtˈsaɪd/","gloss":"lá fora"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-13-07', 'lesson-tenses-b1-13', 7, 'sentence', 'He asked me to close the door.', 'Ele me pediu para fechar a porta.', '/hiː æskt miː tuː kloʊz ðə dɔːr/', 'Pedido: ask + pessoa + to + verbo.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"asked","pos":"verb","ipa":"/æskt/","gloss":"perguntou, pediu"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"close","pos":"verb","ipa":"/kloʊz/","gloss":"fechar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"door","pos":"noun","ipa":"/dɔːr/","gloss":"porta"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-13-08', 'lesson-tenses-b1-13', 8, 'sentence', 'The doctor told me not to run.', 'O médico me disse para não correr.', '/ðə ˈdɑːktər toʊld miː nɑːt tuː rʌn/', 'Ordem negativa: "not to" + verbo.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"doctor","pos":"noun","ipa":"/ˈdɑːktər/","gloss":"médico"},{"surface":"told","pos":"verb","ipa":"/toʊld/","gloss":"contou, disse"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"run","pos":"verb","ipa":"/rʌn/","gloss":"correr; administrar"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-13-09', 'lesson-tenses-b1-13', 9, 'sentence', 'I wonder if she got my message.', 'Será que ela recebeu minha mensagem?', '/aɪ ˈwʌndər ɪf ʃiː ɡɑːt maɪ ˈmɛsɪdʒ/', '"I wonder if" = "será que", com ordem de afirmação.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"wonder","pos":"verb","ipa":"/ˈwʌndər/","gloss":"perguntar-se"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"got","pos":"verb","ipa":"/ɡɑːt/","gloss":"conseguiu, pegou"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"message","pos":"noun","ipa":"/ˈmɛsɪdʒ/","gloss":"mensagem"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-13-10', 'lesson-tenses-b1-13', 10, 'sentence', 'I don''t know what he wants.', 'Não sei o que ele quer.', '/aɪ doʊnt noʊ wʌt hiː wɑːnts/', 'Sem "does": "what he wants", não "what does he want".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"know","pos":"verb","ipa":"/noʊ/","gloss":"saber"},{"surface":"what","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"wants","pos":"verb","ipa":"/wɑːnts/","gloss":"quer"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-tenses-b1-14-01', 'lesson-tenses-b1-14', 1, 'sentence', 'She must be tired.', 'Ela deve estar cansada.', '/ʃiː mʌst biː ˈtaɪərd/', '"Must" de dedução: tenho quase certeza de que sim.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"tired","pos":"adjective","ipa":"/ˈtaɪərd/","gloss":"cansado"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-14-02', 'lesson-tenses-b1-14', 2, 'sentence', 'That can''t be true.', 'Isso não pode ser verdade.', '/ðæt kænt biː truː/', '"Can''t" de dedução: tenho quase certeza de que não. Nunca "mustn''t" com esse sentido.', '[]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"can''t","pos":"auxiliary verb","ipa":"/kænt/","gloss":"não poder"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"true","pos":"adjective","ipa":"/truː/","gloss":"verdadeiro"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-14-03', 'lesson-tenses-b1-14', 3, 'sentence', 'He might be at home.', 'Ele pode estar em casa.', '/hiː maɪt biː æt hoʊm/', '"Might" = talvez, uns 50%.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"might","pos":"modal verb","ipa":"/maɪt/","gloss":"talvez, poderia"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-14-04', 'lesson-tenses-b1-14', 4, 'sentence', 'It could be the neighbor.', 'Pode ser o vizinho.', '/ɪt kʊd biː ðə ˈneɪbər/', '"Could" = possibilidade, como "might".', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"neighbor","pos":"noun","ipa":"/ˈneɪbər/","gloss":"vizinho"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-14-05', 'lesson-tenses-b1-14', 5, 'sentence', 'They may know the answer.', 'Talvez eles saibam a resposta.', '/ðeɪ meɪ noʊ ðə ˈænsər/', '"May" = possibilidade, um pouco mais formal.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"may","pos":"modal verb","ipa":"/meɪ/","gloss":"poder (permissão formal)"},{"surface":"know","pos":"verb","ipa":"/noʊ/","gloss":"saber"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"answer","pos":"noun","ipa":"/ˈænsər/","gloss":"resposta"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-14-06', 'lesson-tenses-b1-14', 6, 'sentence', 'You must be joking!', 'Você só pode estar brincando!', '/juː mʌst biː ˈdʒoʊkɪŋ/', 'Expressão fixa de surpresa.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"joking","pos":"verb","ipa":"/ˈdʒoʊkɪŋ/","gloss":"brincando"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-14-07', 'lesson-tenses-b1-14', 7, 'sentence', 'She must be working late.', 'Ela deve estar trabalhando até tarde.', '/ʃiː mʌst biː ˈwɜːrkɪŋ leɪt/', 'Modal + be + -ing para dedução sobre agora.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"working","pos":"verb","ipa":"/ˈwɜːrkɪŋ/","gloss":"funcionando; trabalhando"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-14-08', 'lesson-tenses-b1-14', 8, 'sentence', 'He can''t be hungry. He just ate.', 'Ele não pode estar com fome. Acabou de comer.', '/hiː kænt biː ˈhʌŋɡri hiː dʒʌst eɪt/', 'A dedução vem com a evidência.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"can''t","pos":"auxiliary verb","ipa":"/kænt/","gloss":"não poder"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"hungry","pos":"adjective","ipa":"/ˈhʌŋɡri/","gloss":"com fome"},{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"just","pos":"adverb","ipa":"/dʒʌst/","gloss":"só, apenas"},{"surface":"ate","pos":"verb","ipa":"/eɪt/","gloss":"comeu"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-14-09', 'lesson-tenses-b1-14', 9, 'sentence', 'This must be your first time here.', 'Esta deve ser sua primeira vez aqui.', '/ðɪs mʌst biː jʊr fɜːrst taɪm hɪr/', '"Must" também para deduzir com gentileza.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"first","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-14-10', 'lesson-tenses-b1-14', 10, 'sentence', 'The keys might be in the car.', 'As chaves podem estar no carro.', '/ðə kiːz maɪt biː ɪn ðə kɑːr/', 'Negativa de "might": "might not" = talvez não.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"keys","pos":"noun","ipa":"/kiːz/","gloss":"chaves"},{"surface":"might","pos":"modal verb","ipa":"/maɪt/","gloss":"talvez, poderia"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-tenses-b1-15-01', 'lesson-tenses-b1-15', 1, 'sentence', 'She must have forgotten.', 'Ela deve ter esquecido.', '/ʃiː mʌst hæv fərˈɡɑːtən/', 'Must have + particípio = quase certeza sobre o passado.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"forgotten","pos":"verb","ipa":"/fərˈɡɑːtən/","gloss":"esquecido"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-15-02', 'lesson-tenses-b1-15', 2, 'sentence', 'He can''t have seen us.', 'Ele não pode ter nos visto.', '/hiː kænt hæv siːn ʌs/', 'Can''t have + particípio = quase certeza de que não aconteceu.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"can''t","pos":"auxiliary verb","ipa":"/kænt/","gloss":"não poder"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"seen","pos":"verb","ipa":"/siːn/","gloss":"visto"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-15-03', 'lesson-tenses-b1-15', 3, 'sentence', 'They might have missed the bus.', 'Eles podem ter perdido o ônibus.', '/ðeɪ maɪt hæv mɪst ðə bʌs/', 'Might have + particípio = talvez tenha acontecido.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"might","pos":"modal verb","ipa":"/maɪt/","gloss":"talvez, poderia"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"missed","pos":"verb","ipa":"/mɪst/","gloss":"perdi"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-15-04', 'lesson-tenses-b1-15', 4, 'sentence', 'I must have left my phone at work.', 'Devo ter deixado o celular no trabalho.', '/aɪ mʌst hæv lɛft maɪ foʊn æt wɜːrk/', 'Dedução sobre algo que você mesmo fez.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-15-05', 'lesson-tenses-b1-15', 5, 'sentence', 'You could have called me.', 'Você podia ter me ligado.', '/juː kʊd hæv kɔːld miː/', '"Could have" também critica: era possível e não fez.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"called","pos":"verb","ipa":"/kɔːld/","gloss":"ligou, chamou"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-15-06', 'lesson-tenses-b1-15', 6, 'sentence', 'It must have been hard for you.', 'Deve ter sido difícil para você.', '/ɪt mʌst hæv bɪn hɑːrd fɔːr juː/', 'Frase de empatia muito usada.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"hard","pos":"adjective","ipa":"/hɑːrd/","gloss":"duro, difícil"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-15-07', 'lesson-tenses-b1-15', 7, 'sentence', 'She couldn''t have known.', 'Ela não tinha como saber.', '/ʃiː ˈkʊdənt hæv noʊn/', '"Couldn''t have" = era impossível.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"couldn''t","pos":"verb","ipa":"/ˈkʊdənt/","gloss":"não podia (could not)"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"known","pos":"verb","ipa":"/noʊn/","gloss":"sabido, conhecido"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-15-08', 'lesson-tenses-b1-15', 8, 'sentence', 'The road must have been closed.', 'A estrada deve ter sido fechada.', '/ðə roʊd mʌst hæv bɪn kloʊzd/', 'Dedução com passiva: must have been + particípio.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"road","pos":"noun","ipa":"/roʊd/","gloss":"estrada"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"closed","pos":"verb","ipa":"/kloʊzd/","gloss":"fechou, fechado"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-15-09', 'lesson-tenses-b1-15', 9, 'sentence', 'He may have taken the wrong train.', 'Ele pode ter pegado o trem errado.', '/hiː meɪ hæv ˈteɪkən ðə rɔːŋ treɪn/', '"May have" = "might have", um pouco mais formal.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"may","pos":"modal verb","ipa":"/meɪ/","gloss":"poder (permissão formal)"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"taken","pos":"verb","ipa":"/ˈteɪkən/","gloss":"pegado, levado"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"wrong","pos":"adjective","ipa":"/rɔːŋ/","gloss":"errado"},{"surface":"train","pos":"noun","ipa":"/treɪn/","gloss":"trem"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-15-10', 'lesson-tenses-b1-15', 10, 'sentence', 'Someone must have taken it by mistake.', 'Alguém deve ter levado por engano.', '/ˈsʌmwʌn mʌst hæv ˈteɪkən ɪt baɪ mɪˈsteɪk/', '"By mistake" = por engano.', '[]'::jsonb, '[{"surface":"Someone","pos":"pronoun","ipa":"/ˈsʌmwʌn/","gloss":"alguém"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"taken","pos":"verb","ipa":"/ˈteɪkən/","gloss":"pegado, levado"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"mistake","pos":"noun","ipa":"/mɪˈsteɪk/","gloss":"erro"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-tenses-b1-16-01', 'lesson-tenses-b1-16', 1, 'sentence', 'If it rains tomorrow, we will stay home.', 'Se chover amanhã, vamos ficar em casa.', '/ɪf ɪt reɪnz təˈmɑːroʊ wiː wɪl steɪ hoʊm/', 'Revisão: primeira condicional.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"rains","pos":"verb","ipa":"/reɪnz/","gloss":"chove"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"stay","pos":"verb","ipa":"/steɪ/","gloss":"ficar"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-16-02', 'lesson-tenses-b1-16', 2, 'sentence', 'If I were you, I would accept the offer.', 'Se eu fosse você, aceitaria a oferta.', '/ɪf aɪ wɜːr juː aɪ wʊd əkˈsɛpt ðə ˈɔːfər/', 'Revisão: segunda condicional.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"accept","pos":"verb","ipa":"/əkˈsɛpt/","gloss":"aceitar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"offer","pos":"noun","ipa":"/ˈɔːfər/","gloss":"oferta"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-16-03', 'lesson-tenses-b1-16', 3, 'sentence', 'If you had told me, I would have helped.', 'Se você tivesse me contado, eu teria ajudado.', '/ɪf juː hæd toʊld miː aɪ wʊd hæv hɛlpt/', 'Revisão: terceira condicional.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"told","pos":"verb","ipa":"/toʊld/","gloss":"contou, disse"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"helped","pos":"verb","ipa":"/hɛlpt/","gloss":"ajudou"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-16-04', 'lesson-tenses-b1-16', 4, 'sentence', 'This bridge was built in 1920.', 'Esta ponte foi construída em 1920.', '/ðɪs brɪdʒ wɑːz bɪlt ɪn/', 'Revisão: passiva no passado.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"bridge","pos":"noun","ipa":"/brɪdʒ/","gloss":"ponte"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"built","pos":"verb","ipa":"/bɪlt/","gloss":"construiu"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-16-05', 'lesson-tenses-b1-16', 5, 'sentence', 'The package has been delivered.', 'O pacote foi entregue.', '/ðə ˈpækɪdʒ hæz bɪn dɪˈlɪvərd/', 'Revisão: passiva no present perfect.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"package","pos":"noun","ipa":"/ˈpækɪdʒ/","gloss":"pacote"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"delivered","pos":"verb","ipa":"/dɪˈlɪvərd/","gloss":"entregue"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-16-06', 'lesson-tenses-b1-16', 6, 'sentence', 'She said she was tired.', 'Ela disse que estava cansada.', '/ʃiː sɛd ʃiː wɑːz ˈtaɪərd/', 'Revisão: discurso indireto.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"said","pos":"verb","ipa":"/sɛd/","gloss":"disse, dito"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"tired","pos":"adjective","ipa":"/ˈtaɪərd/","gloss":"cansado"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-16-07', 'lesson-tenses-b1-16', 7, 'sentence', 'She asked me where I lived.', 'Ela me perguntou onde eu morava.', '/ʃiː æskt miː wɛr aɪ lɪvd/', 'Revisão: pergunta indireta.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"asked","pos":"verb","ipa":"/æskt/","gloss":"perguntou, pediu"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"lived","pos":"verb","ipa":"/lɪvd/","gloss":"morou, viveu"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-16-08', 'lesson-tenses-b1-16', 8, 'sentence', 'She must be tired.', 'Ela deve estar cansada.', '/ʃiː mʌst biː ˈtaɪərd/', 'Revisão: dedução no presente.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"tired","pos":"adjective","ipa":"/ˈtaɪərd/","gloss":"cansado"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-16-09', 'lesson-tenses-b1-16', 9, 'sentence', 'She must have forgotten.', 'Ela deve ter esquecido.', '/ʃiː mʌst hæv fərˈɡɑːtən/', 'Revisão: dedução no passado.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"forgotten","pos":"verb","ipa":"/fərˈɡɑːtən/","gloss":"esquecido"}]'::jsonb, NULL, NULL),
  ('unit-tenses-b1-16-10', 'lesson-tenses-b1-16', 10, 'sentence', 'I wish I had listened to you.', 'Queria ter te escutado.', '/aɪ wɪʃ aɪ hæd ˈlɪsənd tuː juː/', 'Revisão: arrependimento com "I wish".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"wish","pos":"verb","ipa":"/wɪʃ/","gloss":"desejar"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"listened","pos":"verb","ipa":"/ˈlɪsənd/","gloss":"ouviu"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL)
